import{_ as o,o as t,c as a,a2 as l}from"./chunks/framework.D52qfWmk.js";const v=JSON.parse('{"title":"事件循环（Event Loop）","description":"","frontmatter":{},"headers":[],"relativePath":"js/eventloop.md","filePath":"js/eventloop.md"}'),r={name:"js/eventloop.md"};function n(p,e,i,s,c,_){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="事件循环（event-loop）" tabindex="-1">事件循环（Event Loop） <a class="header-anchor" href="#事件循环（event-loop）" aria-label="Permalink to &quot;事件循环（Event Loop） {#事件循环（event-loop）}&quot;">​</a></h1><h2 id="单线程的原因" tabindex="-1">单线程的原因 <a class="header-anchor" href="#单线程的原因" aria-label="Permalink to &quot;单线程的原因&quot;">​</a></h2><blockquote><p>单线程与之用途有关，单线程能够保证一致性，如果有两个线程，一个线程点击了一个元素，另一个删除了一个元素，浏览器以哪一个为准？</p></blockquote><p>单线程指的是单个脚本只能在一个线程上运行，而不是 JavaScript 引擎只有一个线程。</p><h2 id="event-loop" tabindex="-1">Event Loop <a class="header-anchor" href="#event-loop" aria-label="Permalink to &quot;Event Loop&quot;">​</a></h2><ul><li><p>Javascript是单线程的，所有的同步任务都会在主线程中执行。</p></li><li><p>主线程之外，还有一个任务队列。每当一个异步任务有结果了，就往任务队列里塞一个事件。</p></li><li><p>当主线程中的任务，都执行完之后，系统会 “依次” 读取任务队列里的事件。与之相对应的异步任务进入主线程，开始执行。</p></li><li><p>异步任务之间，会存在差异，所以它们执行的优先级也会有区别。大致分为 微任务（micro task，如：Promise、MutaionObserver等）和宏任务（macro task，如：setTimeout、setInterval、I/O等）。同一次事件循环中，微任务永远在宏任务之前执行。</p></li><li><p>主线程会不断重复上面的步骤，直到执行完所有任务。</p></li></ul>',6)])])}const h=o(r,[["render",n]]);export{v as __pageData,h as default};
